let t = tokens(theme);
match status {
    button::Status::Active   => face(Some(t.primary),       t.on_primary, rounded()),
    button::Status::Hovered  => face(Some(t.primary_hover), t.on_primary, rounded()),
    button::Status::Pressed  => face(Some(t.ink),           t.on_primary, rounded()),
    button::Status::Disabled => face(Some(t.line),          t.muted,      rounded()),
}
// rounded() = Border { radius: RADIUS.into(), ..Border::default() }  (RADIUS = 8.0)

// same style function as Primary Button: theme::button_primary
match status {
    Active   => face(Some(t.primary),       t.on_primary, rounded()),
    Hovered  => face(Some(t.primary_hover), t.on_primary, rounded()),
    Pressed  => face(Some(t.ink),           t.on_primary, rounded()),
    Disabled => face(Some(t.line),          t.muted,      rounded()),
}

let t = tokens(theme);
let border = |color| Border { color, width: 1.0, radius: RADIUS.into() };
match status {
    Active   => face(Some(t.raised),   t.text,  border(t.line)),
    Hovered  => face(Some(t.hover),    t.text,  border(t.line_strong)),
    Pressed  => face(Some(t.selected), t.text,  border(t.line_strong)),
    Disabled => face(None,             t.muted, border(t.line)),
}

let t = tokens(theme);
let border = Border { color: t.danger, width: 1.0, radius: RADIUS.into() };
match status {
    Active   => face(None,                 t.danger,    border),
    Hovered  => face(Some(t.danger_soft),  t.danger,    border),
    Pressed  => face(Some(t.danger),       t.on_danger, border),
    Disabled => face(None,                 t.muted,     rounded()),
}

let t = tokens(theme);
match status {
    Active   => face(None,                t.text,  rounded()),
    Hovered  => face(Some(t.hover),       t.text,  rounded()),
    Pressed  => face(Some(t.selected),    t.text,  rounded()),
    Disabled => face(None,                t.muted, rounded()),
}

let t = tokens(theme);
let (border, width) = match status {
    Active   => (t.line, 1.0),
    Hovered  => (t.line_strong, 1.0),
    Focused { .. } => (t.ink, 2.0),   // focus ring
    Disabled => (t.line, 1.0),
};
text_input::Style {
    background: if Disabled { t.chrome.into() } else { t.raised.into() },
    border: Border { color: border, width, radius: RADIUS.into() },
    icon: t.muted, placeholder: t.muted, value: t.text, selection: t.selected,
}

let t = tokens(theme);
match status {
    Active | Disabled => face(None,             t.text, rounded()),
    Hovered           => face(Some(t.hover),    t.text, rounded()),
    Pressed           => face(Some(t.selected), t.text, rounded()),
}

let tag = tokens(theme).tags[hue % 6];
container::Style {
    text_color: Some(tag.text),
    background: Some(tag.fill.into()),
    border: Border { radius: Radius::new(999.0), ..Border::default() },
    ..container::Style::default()
}

let t = tokens(theme);
container::Style {
    text_color: Some(t.muted),
    background: Some(t.chrome.into()),
    border: Border { color: t.line, width: 1.0, radius: Radius::new(999.0) },
    ..container::Style::default()
}

