    Tone::Bloom(Bloom::Running)  => t.stage_running,
    Tone::Bloom(Bloom::Closed)   => t.stage_closed,
    Tone::Bloom(Bloom::Rejected) => t.stage_rejected,
    /* Text, Muted, Ink, OnPrimary, Danger map to t.text, t.muted, t.ink, t.on_primary, t.danger */
}) }

// container: theme::chrome = surface(t.chrome, t.text)
// picker (room switcher), flat until hovered:
let (background, border) = match status {
    Active          => (t.chrome,   t.chrome),
    Hovered         => (t.hover,    t.line_strong),
    Opened { .. }   => (t.selected, t.ink),
};
pick_list::Style { text_color: t.text, placeholder_color: t.muted, handle_color: t.muted,
    background: background.into(),
    border: Border { color: border, width: 1.0, radius: RADIUS.into() } }

